#include <iostream>
#include <string>

struct Animation
{
    std::string name{};
    int first{}, count{};
    float secondsPerFrame{};
    bool loop{};
};

class Player
{
public:
    void play(const Animation& a) {}
    void update(float dt) {}
    int frame() const { return 0; }
    bool finished() const { return false; }

private:
    const Animation* m_anim{};
    float m_time{};
};

int main()
{
    Animation walk{"walk", 0, 4, 0.1f, true};
    Player p{};
    p.play(walk);
    p.update(0.25f);
    std::cout << p.frame() << '\n';
}
